function buildSeries(flat: { date: string; amount: number }[], range: DateRange) {
  const now = new Date();

  if (range === "weekly") {
    const buckets = [{v:0, c:0}, {v:0, c:0}, {v:0, c:0}, {v:0, c:0}];
    flat.forEach((r) => {
      const d = new Date(r.date);
      if (d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear()) {
        const week = Math.min(3, Math.floor((d.getDate() - 1) / 7));
        buckets[week].v += r.amount;
        buckets[week].c += 1;
      }
    });
    return buckets.map((b, i) => ({ label: `Wk ${i + 1}`, value: b.v, count: b.c }));
  }

  const monthsBack = range === "monthly" ? 6 : 12;
  const labels: { label: string; year: number; month: number }[] = [];
  for (let i = monthsBack - 1; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    labels.push({ label: d.toLocaleString(undefined, { month: "short" }), year: d.getFullYear(), month: d.getMonth() });
  }
  return labels.map((l) => {
    const matches = flat.filter((r) => {
      const d = new Date(r.date);
      return d.getFullYear() === l.year && d.getMonth() === l.month;
    });
    return {
      label: l.label,
      value: matches.reduce((a, r) => a + r.amount, 0),
      count: matches.length,
    };
  });
}

