        <a href={link} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg text-[12px] font-bold shadow-sm border transition-colors hover:bg-black/5" style={{ background: t.surface, color: t.green, borderColor: t.border }}>
          <ExternalLink size={14} /> View original photo
        </a>
