      {!previewFailed && currentSrc && (
        <div className="flex-1 relative rounded-xl border overflow-hidden bg-black/5 min-h-[300px]" style={{ borderColor: t.border }}>
          <img
            src={currentSrc}
            alt={`${merchant} receipt`}
            loading="lazy"
            onClick={() => setIsZoomed(true)}
            className="absolute inset-0 w-full h-full object-contain cursor-zoom-in hover:scale-[1.02] transition-transform duration-300"
            style={{ background: t.surfaceAlt }}
            onError={() => {
              if (previewIndex + 1 < previewOptions.length) {
                setPreviewIndex((index) => index + 1);
              } else {
                setPreviewFailed(true);
              }
            }}
          />
        </div>
      )}
      {previewFailed && (
