/** Exports all receipts into a single CSV. */
export function exportAllReceiptsCsv(messages: ReceiptMessage[]) {
  const header = ["Sender", "Status", "Submitted", "Grand Total", "Merchant", "Date", "Item Description", "Item Price"];
  const rows: string[][] = [];
  messages.forEach(m => {
    m.receipts.forEach(r => {
      if (r.items.length === 0) {
        rows.push([m.sender_name, m.status, dateTime(m.createdAt), formatAmount(m.grand_total, r.currency), r.merchant_name, `${r.date} ${r.time ?? ""}`.trim(), "", ""]);
      } else {
        r.items.forEach(it => {
          rows.push([m.sender_name, m.status, dateTime(m.createdAt), formatAmount(m.grand_total, r.currency), r.merchant_name, `${r.date} ${r.time ?? ""}`.trim(), it.description, formatAmount(it.price, r.currency)]);
        });
      }
    });
  });

  const csv = [header, ...rows].map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `All_Receipts_${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

